package cl.javier.starwars.service;
import cl.javier.starwars.domain.*; import cl.javier.starwars.repository.*; import tools.jackson.databind.JsonNode; import org.slf4j.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*;
@Service public class SyncService{
 private static final Logger log=LoggerFactory.getLogger(SyncService.class); private final SwapiClient swapi; private final CharacterRepository characters; private final FilmRepository films; private final VehicleRepository vehicles; private final StarshipRepository starships;
 public SyncService(SwapiClient s,CharacterRepository c,FilmRepository f,VehicleRepository v,StarshipRepository st){swapi=s;characters=c;films=f;vehicles=v;starships=st;}
 @Transactional public SyncResult sync(){List<JsonNode> people=swapi.allPeople();Map<String,Film> filmCache=new HashMap<>();Map<String,Vehicle> vehicleCache=new HashMap<>();Map<String,Starship> starshipCache=new HashMap<>();int relations=0;for(JsonNode p:people){long id=SwapiClient.id(text(p,"url"));CharacterEntity c=characters.findById(id).orElseGet(()->new CharacterEntity(id));c.update(text(p,"name"),text(p,"height"),text(p,"mass"),text(p,"gender"),birthOrder(text(p,"birth_year")));c.getFilms().clear();c.getVehicles().clear();c.getStarships().clear();for(JsonNode u:p.path("films")){String url=u.asText();c.getFilms().add(filmCache.computeIfAbsent(url,x->upsertFilm(swapi.get(x),vehicleCache,starshipCache)));relations++;}for(JsonNode u:p.path("vehicles")){String url=u.asText();c.getVehicles().add(vehicleCache.computeIfAbsent(url,x->upsertVehicle(swapi.get(x))));relations++;}for(JsonNode u:p.path("starships")){String url=u.asText();c.getStarships().add(starshipCache.computeIfAbsent(url,x->upsertStarship(swapi.get(x))));relations++;}characters.save(c);}log.info("Sincronización SWAPI finalizada: {} personajes, {} relaciones",people.size(),relations);return new SyncResult(people.size(),films.count(),vehicles.count(),starships.count(),relations);}
 private Film upsertFilm(JsonNode n,Map<String,Vehicle> vehicleCache,Map<String,Starship> starshipCache){long id=SwapiClient.id(text(n,"url"));Film f=films.findById(id).orElseGet(()->new Film(id));f.update(text(n,"title"),n.path("episode_id").asInt(),text(n,"director"),text(n,"producer"),LocalDate.parse(text(n,"release_date")));f.getVehicles().clear();f.getStarships().clear();for(JsonNode u:n.path("vehicles")){String url=u.asText();f.getVehicles().add(vehicleCache.computeIfAbsent(url,x->upsertVehicle(swapi.get(x))));}for(JsonNode u:n.path("starships")){String url=u.asText();f.getStarships().add(starshipCache.computeIfAbsent(url,x->upsertStarship(swapi.get(x))));}return films.save(f);}
 private Vehicle upsertVehicle(JsonNode n){long id=SwapiClient.id(text(n,"url"));Vehicle v=vehicles.findById(id).orElseGet(()->new Vehicle(id));v.update(text(n,"name"),text(n,"model"),text(n,"manufacturer"),text(n,"vehicle_class"));return vehicles.save(v);}
 private Starship upsertStarship(JsonNode n){long id=SwapiClient.id(text(n,"url"));Starship s=starships.findById(id).orElseGet(()->new Starship(id));s.update(text(n,"name"),text(n,"model"),text(n,"manufacturer"),text(n,"starship_class"));return starships.save(s);}
 private static String text(JsonNode n,String key){return n.path(key).asText();} private static Integer birthOrder(String v){try{return Integer.valueOf(v.replaceAll("[^0-9]",""));}catch(Exception e){return null;}}
 public record SyncResult(int characters,long films,long vehicles,long starships,int relations){}
}
